DECLARE
 people jsonb := $people$[{"id":"vilhelm-hammershoi","name":"Vilhelm Hammershøi","name_ko":"빌헬름 함메르쇼이","source_ids":["smk:180_person","met:165225"],"artwork_ids":["smk-kms3696","smk-kms7444","smk-kms3352","smk-kms1542","met-441933"],"profile":{"lifespan":"1864–1916","context":"덴마크 · 회화 · 실내·초상·도시 풍경","description":"덴마크 코펜하겐에서 활동한 화가로, 절제된 색채와 실내에 들어오는 빛을 통해 고요한 공간을 그렸습니다. 스트란게데의 집을 아침과 낮, 밤에 반복해 그렸고, 비어 있는 방이나 아내 이다가 등장하는 일상의 장면을 남겼습니다. 실내화와 함께 초상화·도시 풍경도 살펴볼 수 있습니다.","sources":[{"label":"메트로폴리탄 미술관 · 함메르쇼이 작가 정보 및 달빛 해설","url":"https://www.metmuseum.org/art/collection/search/441933"},{"label":"덴마크 국립미술관 · 함메르쇼이 연구 아카이브","url":"https://hammershoi.smk.dk/"}],"related_post_ids":[]}}]$people$::jsonb;
 works jsonb := $works$[{"id":"smk-kms3696","museum":"SMK – National Gallery of Denmark","title":"Stue i Strandgade med solskin på gulvet","title_ko":"바닥에 햇빛이 드는 스트란게데의 실내","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1901","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 46.5 x 52 cm; Brutto: 63.9 x 70.2 x 5.5 cm","dimensions_ko":"액자 제외: 46.5 × 52 cm; 액자 포함: 63.9 × 70.2 × 5.5 cm","description":"스트란게데의 실내에서 창을 통과한 햇빛이 바닥에 격자무늬를 만드는 장면입니다. 미술관은 회색조와 은빛 창의 빛, 앉아 있는 인물과 어두운 가구의 선이 이루는 균형에 주목합니다.","culture":"Denmark","accession":"KMS3696","source_url":"https://open.smk.dk/artwork/image/KMS3696","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS3696","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/3197xr831_KMS3696.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi8zMTk3eHI4MzFfS01TMzY5Ni50aWYuanAyL2Z1bGwvZnVsbC8wL25hdGl2ZS5qcGciLCJwdWJsaWNfZG9tYWluIjp0cnVlLCJvYmplY3RfbnVtYmVyIjoiS01TMzY5NiIsIm51bSI6IiJ9XQ==/KMS3696.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["인물과 일상","풍경과 빛"],"image_width":1024,"image_height":900,"image_bytes":122925,"sha256":"70f9550d713077447f7aa0b0a9f273a366d2992e629368ab68e7d50536176086","collected_at":"2026-10-13T00:01:08.556Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"smk-kms7444","museum":"SMK – National Gallery of Denmark","title":"Interiør med kunstnerens staffeli","title_ko":"화가의 이젤이 있는 실내","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1910","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 84 x 69 cm; Brutto: 98.4 x 83.5 x 8.6 cm","dimensions_ko":"액자 제외: 84 × 69 cm; 액자 포함: 98.4 × 83.5 × 8.6 cm","description":"코펜하겐 브레드게데 25번지의 집에서 제작한 실내화입니다. 관람자에게 등을 돌린 캔버스와 열린 문 너머의 테이블·그릇이 공간을 이어 줍니다. 같은 구도의 다른 작품과 구별되는 1910년 소장품이며, 치수는 SMK 소장품 API에 기록된 값을 따릅니다.","culture":"Denmark","accession":"KMS7444","source_url":"https://open.smk.dk/artwork/image/KMS7444","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS7444","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/rx913s91d_KMS7444.tif.reconstructed.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi9yeDkxM3M5MWRfS01TNzQ0NC50aWYucmVjb25zdHJ1Y3RlZC50aWYuanAyL2Z1bGwvZnVsbC8wL25hdGl2ZS5qcGciLCJwdWJsaWNfZG9tYWluIjp0cnVlLCJvYmplY3RfbnVtYmVyIjoiS01TNzQ0NCIsIm51bSI6IiJ9XQ==/KMS7444.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["인물과 일상"],"image_width":1024,"image_height":1248,"image_bytes":85975,"sha256":"e89752eab049fb0525644c7991fa81679c598b307cf73c99703145cf20491cf0","collected_at":"2026-10-13T00:01:08.556Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"smk-kms3352","museum":"SMK – National Gallery of Denmark","title":"Kunstnerens hustru Ida Hammershøi med en tekop","title_ko":"찻잔을 든 아내 이다 함메르쇼이","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1907","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 91 x 73.5 cm; Brutto: 94 x 76 x 4.2 cm","dimensions_ko":"액자 제외: 91 × 73.5 cm; 액자 포함: 94 × 76 × 4.2 cm","description":"작가의 아내 이다를 찻잔과 함께 그린 1907년 초상화입니다. 흰 찻잔과 테이블이 검은 옷과 어두운 배경 앞에서 밝게 드러납니다. 인물의 얼굴과 손, 시선의 방향을 중심으로 일상의 잠깐을 구성했습니다.","culture":"Denmark","accession":"KMS3352","source_url":"https://open.smk.dk/artwork/image/KMS3352","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS3352","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/pn89d956v_KMS3352-cropped.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi9wbjg5ZDk1NnZfS01TMzM1Mi1jcm9wcGVkLnRpZi5qcDIvZnVsbC9mdWxsLzAvbmF0aXZlLmpwZyIsInB1YmxpY19kb21haW4iOnRydWUsIm9iamVjdF9udW1iZXIiOiJLTVMzMzUyIiwibnVtIjoiIn1d/KMS3352.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["인물과 일상"],"image_width":1024,"image_height":1288,"image_bytes":105279,"sha256":"626372bd19e0eb7c08e17d31a74c6ec8890e3cab4fee6c1786f26f0115bd9e58","collected_at":"2026-10-13T00:01:08.556Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"smk-kms1542","museum":"SMK – National Gallery of Denmark","title":"Amalienborg Plads","title_ko":"아말리엔보르 광장","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1896","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 136.5 x 136.5 cm; Brutto: 149 x 148.8 x 8 cm","dimensions_ko":"액자 제외: 136.5 × 136.5 cm; 액자 포함: 149 × 148.8 × 8 cm","description":"코펜하겐의 크리스티안 8세 궁에서 바라본 아말리엔보르 광장을 그린 작품입니다. 정사각형 화면에 궁전의 창과 벽면, 앞쪽의 기마상을 배치했습니다. 미술관 연구 아카이브는 이 시점과 건축의 선이 이루는 구도에 주목합니다.","culture":"Denmark","accession":"KMS1542","source_url":"https://open.smk.dk/artwork/image/KMS1542","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS1542","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/jq085p313_KMS1542.tif.reconstructed.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi9qcTA4NXAzMTNfS01TMTU0Mi50aWYucmVjb25zdHJ1Y3RlZC50aWYuanAyL2Z1bGwvZnVsbC8wL25hdGl2ZS5qcGciLCJwdWJsaWNfZG9tYWluIjp0cnVlLCJvYmplY3RfbnVtYmVyIjoiS01TMTU0MiIsIm51bSI6IiJ9XQ==/KMS1542.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["풍경과 빛"],"image_width":1024,"image_height":1019,"image_bytes":92755,"sha256":"9927e2f930d53936ac55fa9301b8e6658e5b7aa670ecda9f01d039d8d6bc2f9e","collected_at":"2026-10-13T00:01:08.556Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"met-441933","museum":"The Metropolitan Museum of Art","title":"Moonlight, Strandgade 30","title_ko":"달빛, 스트란게데 30번지","artist":"Vilhelm Hammershøi","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1900–1906","medium":"Oil on canvas","medium_ko":"캔버스에 유채","dimensions":"16 1/8 x 20 1/8 in. (41 x 51.1 cm)","dimensions_ko":"41 × 51.1 cm","description":"코펜하겐 스트란게데 30번지의 집을 달빛 아래에서 그린 실내화입니다. 깊은 연보라색과 부드러운 붓질로 빛을 표현하고, 비어 있는 방의 기하학적 구조를 드러냈습니다. 창 너머에는 안뜰을 사이에 둔 집의 다른 부분이 보입니다.","culture":"Danish","accession":"2012.203","source_url":"https://www.metmuseum.org/art/collection/search/441933","api_url":"https://collectionapi.metmuseum.org/public/collection/v1/objects/441933","preview_url":"https://images.metmuseum.org/CRDImages/ep/web-large/DP273105.jpg","image_url":"https://images.metmuseum.org/CRDImages/ep/original/DP273105.jpg","license":"CC0","license_evidence":{"isPublicDomain":true},"policy_url":"https://www.metmuseum.org/hubs/open-access","themes":["풍경과 빛"],"image_width":600,"image_height":479,"image_bytes":68469,"sha256":"1527a5632b560abe412faaad06422d014bfebddbb41f31a2d31f54a1e2588727","collected_at":"2026-10-13T00:01:08.556Z","title_ko_status":"working_translation","themes_status":"editorial_classification"}]$works$::jsonb;
BEGIN
 LOCK TABLE public.artists, public.artworks, public.artwork_artists IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(people) item JOIN public.artists a ON a.id=item->>'id' WHERE a.name IS DISTINCT FROM item->>'name' OR a.name_ko IS DISTINCT FROM item->>'name_ko' OR to_jsonb(a.source_ids) IS DISTINCT FROM item->'source_ids' OR a.profile IS DISTINCT FROM item->'profile') THEN
  RAISE EXCEPTION 'Artist ID conflict: no existing content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artworks w ON w.id=item->>'id' WHERE w.data IS DISTINCT FROM item - 'artist_ids') THEN
  RAISE EXCEPTION 'Artwork ID conflict: no existing content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artwork_artists link ON link.artwork_id=item->>'id' WHERE NOT (item->'artist_ids' ? link.artist_id)) THEN
  RAISE EXCEPTION 'Conflicting artist attribution: no existing content was changed';
 END IF;
 INSERT INTO public.artists(id,name,name_ko,source_ids,profile)
 SELECT item->>'id',item->>'name',item->>'name_ko',ARRAY(SELECT jsonb_array_elements_text(item->'source_ids')),item->'profile' FROM jsonb_array_elements(people) item ON CONFLICT (id) DO NOTHING;
 INSERT INTO public.artworks(id,data)
 SELECT item->>'id',item - 'artist_ids' FROM jsonb_array_elements(works) item ON CONFLICT (id) DO NOTHING;
 INSERT INTO public.artwork_artists(artwork_id,artist_id)
 SELECT item->>'id',person FROM jsonb_array_elements(works) item CROSS JOIN LATERAL jsonb_array_elements_text(item->'artist_ids') person ON CONFLICT DO NOTHING;
END;
$catalog_addition$;
